const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

const docs = (extra = []) => [
  { id: 'one', tenant: 'a', owner: 'u', deleted: false, archived: false },
  { id: 'two', tenant: 'a', owner: 'w', deleted: false, archived: false },
  { id: 'gone', tenant: 'a', owner: 'u', deleted: true, archived: false },
  { id: 'far', tenant: 'b', owner: 'u', deleted: false, archived: false },
  { id: 'old', tenant: 'a', owner: 'u', deleted: false, archived: true },
  ...extra,
];
const mk = (extra) => {
  const repo = new DocumentRepository(docs(extra));
  return { repo, service: new DocumentService(repo) };
};
const actor = (role, tenant = 'a', user = 'u') => ({ tenant, user, role });
const snapshot = (repo) => JSON.stringify(repo.documents) + JSON.stringify(repo.audit);

// admin may archive any visible document
let { repo, service } = mk();
service.archive(actor('admin'), 'one');
assert.equal(repo.documents[0].archived, true);
assert.deepEqual(repo.audit, [{ actor: 'u', document: 'one' }]);

// repeating archive on an archived visible document is a no-op
service.archive(actor('admin'), 'one');
assert.deepEqual(repo.audit, [{ actor: 'u', document: 'one' }]);
service.archive(actor('admin'), 'old'); // already archived -> no-op, no error
assert.deepEqual(repo.audit, [{ actor: 'u', document: 'one' }]);

// admin: not found for missing, deleted, foreign tenant
for (const id of ['missing', 'gone', 'far']) {
  assert.throws(() => service.archive(actor('admin'), id), /not found/, id);
}

// editor may archive only owned visible documents
({ repo, service } = mk());
service.archive(actor('editor'), 'one');
assert.equal(repo.documents[0].archived, true);
assert.deepEqual(repo.audit, [{ actor: 'u', document: 'one' }]);
assert.throws(() => service.archive(actor('editor', 'a', 'w'), 'one'), /forbidden/);
assert.throws(() => service.archive(actor('editor'), 'two'), /forbidden/); // owned by w
assert.throws(() => service.archive(actor('editor'), 'far'), /not found/); // foreign tenant
assert.throws(() => service.archive(actor('editor'), 'gone'), /not found/); // deleted

// viewer never may archive
({ repo, service } = mk());
assert.throws(() => service.archive(actor('viewer'), 'one'), /forbidden/);
assert.throws(() => service.archive(actor('viewer'), 'old'), /forbidden/); // permission first, even though archived

// permission is still enforced on already-archived visible documents
assert.throws(() => service.archive(actor('editor', 'a', 'w'), 'old'), /forbidden/); // not owner, archived doc still guarded

// failures leave every document and audit entry unchanged
const before = snapshot(repo);
for (const bad of [
  () => service.archive(actor('viewer'), 'one'),
  () => service.archive(actor('editor'), 'two'),
  () => service.archive(actor('admin'), 'missing'),
  () => service.archive(actor('admin'), 'gone'),
  () => service.archive(actor('admin'), 'far'),
  () => service.archive(actor('admin', 'b'), 'one'),
]) {
  assert.throws(bad, /not found|forbidden/);
  assert.equal(snapshot(repo), before);
}

console.log('AUTH CHECKS OK');

