import { Actor, Document } from './types';
import { DocumentRepository } from './repository';

export class DocumentService {
  constructor(private readonly repository: DocumentRepository) {}
  archive(actor: Actor, id: string): void {
    const document = this.repository.find(id);
    if (!isVisible(document, actor)) throw new Error('not found');
    if (!isAuthorized(actor, document)) throw new Error('forbidden');
    if (!document.archived) this.repository.archive(document, actor.user);
  }
}

function isVisible(document: Document | undefined, actor: Actor): document is Document {
  return document !== undefined && !document.deleted && document.tenant === actor.tenant;
}

function isAuthorized(actor: Actor, document: Document): boolean {
  switch (actor.role) {
    case 'admin':
      return true;
    case 'editor':
      return document.owner === actor.user;
    default:
      return false;
  }
}
